export function getLocalizedWork(work: CatalogWork, lang: SiteLang): CatalogWork {
  const dict = lang === 'es' ? WORKS_ES : lang === 'va' ? WORKS_VA : WORKS_PT;
  const entry = dict[work.id];
  if (entry) {
    return {
      ...work,
      title: entry.title,
      humanTitle: entry.humanTitle,
      date: entry.date,
      periodical: entry.periodical,
      city: entry.city,
      signature: entry.signature,
      summary: entry.summary,
      excerpt: entry.transcription,
      excerptTranslation: entry.note,
    };
  }
  return work;
}

export function getLocalizedWorksList(lang: SiteLang): CatalogWork[] {
  return CATALOG_WORKS.map((w) => getLocalizedWork(w, lang));
}
